import 'server-only';

/**
 * THE HANDBOOK - "How Atlas works" and "FAQ / Help" merged into one (26 Sep
 * 2026), in English and Hindi.
 *
 * SERVER-ONLY ON PURPOSE. Each chapter and question carries the lowest level
 * that may read it. The page filters on the server and sends the browser only
 * what that person may see, so a helper cannot find the admin chapters in the
 * page source or in a downloaded copy. Nothing here may be imported by a
 * client component.
 *
 * Levels, lowest first:
 *   field   - technicians, helpers: everyone signed in
 *   office  - office staff and managers (see levelFor)
 *   admin   - people who change settings or users
 *
 * `migrated` chapters are for a business that moved from an old system
 * (today: Vcare). They name Vcare's own old screens and records.
 */

import type { Level } from '@/lib/levels';
export { levelFor, LEVELS, type Level } from '@/lib/levels';

export const LEVEL_LABEL: Record<Level, Txt> = {
  field: { en: 'Field team', hi: 'फ़ील्ड टीम' },
  office: { en: 'Office & managers', hi: 'ऑफ़िस और मैनेजर' },
  admin: { en: 'Admin', hi: 'एडमिन' },
};

export interface Txt { en: string; hi: string }
export interface HbLink { href: string; label: Txt }
export interface HbStep { t: Txt; p: Txt; links?: HbLink[] }
export interface HbFaq { q: Txt; a: Txt; links?: HbLink[]; level: Level }
export interface HbTable { head: Txt[]; rows: (Txt | string)[][]; linkCol?: number }
export interface HbChapter {
  id: string;
  level: Level;
  group: Txt;
  title: Txt;
  purpose: Txt;
  steps?: HbStep[];
  faqs?: HbFaq[];
  table?: HbTable;
  notes?: { tone: 'tip' | 'warn' | 'good'; text: Txt }[];
  migrated?: boolean;
}

const T = (en: string, hi: string): Txt => ({ en, hi });
const L = (href: string, en: string, hi: string): HbLink => ({ href, label: T(en, hi) });

